import{_ as o,C as a,o as s,c as i,E as t,a2 as l}from"./chunks/framework.DyLyN3RJ.js";const c="/joinwell52/assets/boundaryxp-cycle-20261114/boundaryxp-cycle.en.svg",d="/joinwell52/assets/boundaryxp-cycle-20261114/boundaryxp-workbench.en.jpg",k=JSON.parse('{"title":"BoundaryXP: Make an AI Team’s Task Boundaries Visible","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"BoundaryXP: Make an AI Team’s Task Boundaries Visible","date":"2026-11-14","published_date":"2026-11-14","column":"open-source-engineering","category":"daily","article_type":"project-research","edition":"research-center","research_question":"How does BoundaryXP detect a plan that fails when individually feasible subtasks are combined?","summary":"Every AI subtask may look feasible while the combined plan is impossible. BoundaryXP links 7+1 task requirements to source evidence and deterministic checks, with a paper, live demo, and MCP integration.","cover":"/assets/boundaryxp-cycle-20261114/boundaryxp-cycle.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Public saved cases, 625-case analysis and selected mathematical reruns; no new product-model or MCP-host analysis","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-14-boundaryxp-local-global-cycle.md","filePath":"en/research/2026-11-14-boundaryxp-local-global-cycle.md","lastUpdated":1794662329000}'),h={name:"en/research/2026-11-14-boundaryxp-local-global-cycle.md"};function p(u,e,m,b,g,y){const r=a("ArticleCover"),n=a("ArticleTableScroll");return s(),i("div",null,[t(r,{image:"/assets/boundaryxp-cycle-20261114/boundaryxp-cycle.cover-v1.png",kicker:"Product study · AI task boundaries",title:"BoundaryXP: Make an AI Team’s Task Boundaries Visible",summary:"Every AI subtask may look feasible while the combined plan is impossible. BoundaryXP links 7+1 task requirements to source evidence and deterministic checks, with a paper, live demo, and MCP integration.",version:"2026-11-14",languageHref:"/zh/research/2026-11-14-boundaryxp-local-global-cycle",languageLabel:"中文"}),t(n,{language:"en"}),e[0]||(e[0]=l('<h1 id="boundaryxp-make-an-ai-team-s-task-boundaries-visible" tabindex="-1">BoundaryXP: Make an AI Team’s Task Boundaries Visible <a class="header-anchor" href="#boundaryxp-make-an-ai-team-s-task-boundaries-visible" aria-label="Permalink to &quot;BoundaryXP: Make an AI Team’s Task Boundaries Visible&quot;">​</a></h1><p>Give an AI team a job and it can quickly split the work among planners, executors, and reviewers. If every member says “my part is feasible,” does that mean the job as a whole can be done?</p><p><strong>BoundaryXP</strong> is a task-boundary analysis tool built for that question. It examines a complete task and its subtasks, links requirements back to source text, checks both individual and combined plans, and explains whether a plan is <strong>violated, within bounds, or unresolved</strong>. It now has a <a href="https://github.com/joinwell52-AI/BoundaryXP" target="_blank" rel="noreferrer">public product repository</a>, a <a href="https://doi.org/10.5281/zenodo.24072738" target="_blank" rel="noreferrer">paper on its 7+1 method</a>, an <a href="https://boundaryxp-workbench-demo.joinwell52.chatgpt.site/" target="_blank" rel="noreferrer">interactive demo</a>, and an <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/docs/mcp/npm/INSTALL.md" target="_blank" rel="noreferrer">MCP package</a> for compatible AI hosts.</p><h2 id="one-example-shows-why-the-tool-exists" tabindex="-1">One example shows why the tool exists <a class="header-anchor" href="#one-example-shows-why-the-tool-exists" aria-label="Permalink to &quot;One example shows why the tool exists&quot;">​</a></h2><p>In a laboratory task specification, four events must be scheduled in the same round: safety review, equipment startup, packaging, and sample testing. The parent task requires review to finish before startup. Three groups add their own orderings: startup before packaging, packaging before testing, and testing before review.</p><p>Each group&#39;s addition is feasible <strong>when checked alongside the parent on its own</strong>. Joined together, the requirements say:</p><blockquote><p>Safety review → startup → packaging → testing → safety review.</p></blockquote><p>The first event must wait for the last. The plan has no starting point. BoundaryXP&#39;s public <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/docs/demo/reports/R389-383.en.md" target="_blank" rel="noreferrer">RT044 saved case</a> preserves one parent, six children, and ten queries. The parent and each child ordering pass their separate feasibility checks; <strong>the joint query reports a violation</strong>. The source fixes the events to the same round and occurrence, so an imagined second packaging step cannot dissolve the loop. This is a counterexample in a task specification, not an actual laboratory accident.</p><figure><img src="'+c+'" alt="In RT044 the parent and three groups each add a feasible ordering; together safety review A, startup D, packaging B, and testing C form a strict cycle"><figcaption>The conflict arises from the combination. It does not show that any one group violated the parent on its own.</figcaption></figure><p><strong><a href="https://boundaryxp-workbench-demo.joinwell52.chatgpt.site/?lang=en#case=R389-383&amp;axis=A&amp;view=radar&amp;lang=en" target="_blank" rel="noreferrer">Open the RT044 demo to inspect the task tree, 7+1 radar, and source evidence →</a></strong></p><figure><img src="'+d+'" alt="BoundaryXP English demo workbench with parent-child task tree on the left, 7+1 boundary radar in the center, and source clauses and evidence on the right"><figcaption>BoundaryXP’s English demo screenshot shows the separate ENG20-003 case: the task tree, linked boundary map, and source clauses remain visible together. The demo replays saved results rather than running a fresh analysis.</figcaption></figure><p>The product&#39;s value is more than a red status label. It retains <strong>which requirement came from which passage, which occurrence it describes, and how it connects to another subtask</strong>. Whoever revises the plan can inspect the complete path and recheck it after changing an ordering.</p><h2 id="_7-1-makes-requirements-connectable-and-inspectable" tabindex="-1">7+1 makes requirements connectable and inspectable <a class="header-anchor" href="#_7-1-makes-requirements-connectable-and-inspectable" aria-label="Permalink to &quot;7+1 makes requirements connectable and inspectable&quot;">​</a></h2><p>“7+1” does not mean eight scores or eight agents. BoundaryXP organizes task requirements into seven views: <strong>input I, output O, actions A, people and responsibility P, resources R, version and basis V, completion and stopping C</strong>. A separate <strong>prohibition boundary B</strong> records what must not happen. In everyday terms: what goes in, what must come out, who acts, under which rules, when the work ends, and what is forbidden.</p><p>The important part is the <strong>relationship among those views</strong>. In RT044, TEST&#39;s packaging must be the same event as LAB&#39;s packaging; SAFETY&#39;s review must be the parent&#39;s review. If a system mistakenly links different occurrences, precise arithmetic solves the wrong problem. BoundaryXP keeps identity, ordering, and source provenance together so a cross-team plan can be checked as a whole.</p><p>For domain-specific terms, BoundaryXP can also bind <strong>L2 industry and L3 enterprise dictionaries</strong>, recording the selected versions and digests so a role, device, or action can be interpreted against inspectable context. A dictionary helps interpret a task; a role name does not grant business authority. The <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/docs/mcp/TOOLS.md" target="_blank" rel="noreferrer">dictionary tools</a> are documented with the product.</p><p>This is why the demo has more than pass and fail. Three cases are especially revealing:</p><table tabindex="0"><thead><tr><th>Demo case</th><th>Boundary question</th><th>What to inspect</th></tr></thead><tbody><tr><td><a href="https://boundaryxp-workbench-demo.joinwell52.chatgpt.site/?lang=en#case=R389-383&amp;axis=A&amp;view=radar&amp;lang=en" target="_blank" rel="noreferrer">RT044: joint violation</a></td><td>Feasible parts form an impossible cycle</td><td>Task tree, source orderings, joint conflict</td></tr><tr><td><a href="https://boundaryxp-workbench-demo.joinwell52.chatgpt.site/?lang=en#case=R389-381&amp;axis=R&amp;view=radar&amp;lang=en" target="_blank" rel="noreferrer">RT042: within bounds</a></td><td>Instrument use at 10–11 and 11–12 touches at the release time</td><td>No overlap under the stated half-open intervals</td></tr><tr><td><a href="https://boundaryxp-workbench-demo.joinwell52.chatgpt.site/?lang=en#case=R389-153&amp;axis=P&amp;view=radar&amp;lang=en" target="_blank" rel="noreferrer">L23-050: unresolved</a></td><td>“He will confirm” does not identify one final owner</td><td>Missing identity remains unresolved</td></tr></tbody></table><p>Together they show the intended behavior: <strong>report a known conflict, avoid inventing a conflict, and preserve a genuinely missing fact.</strong></p><h2 id="from-a-paper-to-cursor-and-codex" tabindex="-1">From a paper to Cursor and Codex <a class="header-anchor" href="#from-a-paper-to-cursor-and-codex" aria-label="Permalink to &quot;From a paper to Cursor and Codex&quot;">​</a></h2><p>The <a href="https://doi.org/10.5281/zenodo.24072738" target="_blank" rel="noreferrer">BXP paper</a> states the 7+1 relational method and the conditions under which formal boundary checks hold. Its <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/docs/paper/materials/manuscript.en.md" target="_blank" rel="noreferrer">public research materials</a> include 625 saved task groups, 3,219 nodes, and 3,469 queries. Against a pinned public revision, we reran the classification script, six selected mathematical witnesses, and nine saved cost checks; all passed. Our <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-14-boundaryxp/00-report.en.md" target="_blank" rel="noreferrer">rerun record</a> lists the commands and scope. The numbers show the size and traceability of the research package. <strong>The 625/625 whole-case agreement is agreement within current saved records, not accuracy on unseen tasks.</strong></p><p>The fastest way to understand the product is the <a href="https://boundaryxp-workbench-demo.joinwell52.chatgpt.site/" target="_blank" rel="noreferrer">interactive demo</a>: open a case, move between the parent-child tree, eight-axis relations, source passages, and full report. It replays B-332 saved results.</p><p>To bring BoundaryXP into an AI workflow, start with the <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/docs/mcp/npm/INSTALL.md" target="_blank" rel="noreferrer">MCP installation guide</a>. The current <strong>0.4.0-rc.6 prerelease</strong> targets Windows x64 and connects to compatible hosts such as Cursor and Codex through standard MCP. It offers <strong>18 tools, ten resources, and a local browser workbench</strong>. The package includes the compiled Core, so there is no separate BoundaryXP server to set up. Fresh analysis uses a model API that the user configures. The public repository contains the paper, cases, documentation, and release packages; original Core implementation source is maintained separately.</p><p>The workflow is deliberately explicit: <strong>import and preview</strong> a complete task tree; <strong>save</strong> the confirmed revision; request one model analysis; let Core check supported structures and operands deterministically; then inspect <strong>source text, model judgment, calculation receipt, and unresolved items</strong>. Saved operands can be recomputed without another model call. Opening the workbench does not silently submit an analysis, and a boundary finding is not business authorization. The <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/docs/mcp/TOOLS.md" target="_blank" rel="noreferrer">tool reference</a> makes each tool&#39;s effects clear.</p><h2 id="what-boundaryxp-makes-possible-to-ask" tabindex="-1">What BoundaryXP makes possible to ask <a class="header-anchor" href="#what-boundaryxp-makes-possible-to-ask" aria-label="Permalink to &quot;What BoundaryXP makes possible to ask&quot;">​</a></h2><p>In multi-agent work, the missing piece is often not an answer but <strong>which version of the task, which source passage, and which exact object that answer refers to—and whether all parts can coexist</strong>. BoundaryXP preserves those links, turning “why violated?”, “why within bounds?”, and “what is still unknown?” into questions a human can investigate.</p><p>Its boundary is visible too: deterministic Core checks the problem as represented; it cannot automatically prove that a model understood every source sentence. The public demo replays saved results, and an analysis result does not grant execution authority. Those distinctions make the tool more useful for serious evaluation with real task specifications.</p><p><strong><a href="https://boundaryxp-workbench-demo.joinwell52.chatgpt.site/" target="_blank" rel="noreferrer">Try the BoundaryXP demo →</a></strong> · <a href="https://github.com/joinwell52-AI/BoundaryXP" target="_blank" rel="noreferrer">Explore the public repository</a> · <a href="https://doi.org/10.5281/zenodo.24072738" target="_blank" rel="noreferrer">Read the paper</a> · <a href="https://github.com/joinwell52-AI/BoundaryXP/blob/main/docs/mcp/npm/INSTALL.md" target="_blank" rel="noreferrer">Connect through MCP</a></p><p>If your agents each say their subtask is feasible, <strong>who has checked the boundary of the plan they form together?</strong></p>',29))])}const w=o(h,[["render",p]]);export{k as __pageData,w as default};
